"""Compile the m254tg source (source_tg.py, generated by gen.py; env M254TG_SRC selects another) with Wade's TMBuilder and extract its program DAG.

Writes m254tg_<source>_rebuilt.tm (Wade-framework TM: states named after subroutines) and prints DAG statistics;
load_dag() reads the frozen ../../machine/m254tg_wade.tm for source_tg.
The Wade-framework compilation is only a vehicle for the program graph: the third party's 254-state
table uses its own interpreter, but the program (decision DAG over the 9 registers) is the same source.

Usage: python build_dag.py            (from any directory)
Import: from build_dag import load_dag  ->  (nodes, regidx)
"""
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__))
ZF = os.path.normpath(os.path.join(HERE, '..', '..', '..'))
sys.path.insert(0, os.path.join(ZF, 'generator'))                  # Wade's TMBuilder
sys.path.insert(0, os.path.join(ZF, 'tools'))                      # dag.py
sys.path.insert(0, os.path.join(HERE, '..', '..', 'machine'))      # source_tg.py
sys.path.insert(0, HERE)

SRC_MOD = os.environ.get('M254TG_SRC', 'source_tg')          # source_<variant> written by gen.py
FROZEN = os.path.join(HERE, '..', '..', 'machine', 'm254tg_wade.tm')
OUT = os.path.join(HERE, f'm254tg_{SRC_MOD}_rebuilt.tm')            # build() never overwrites the frozen file
TM_PATH = FROZEN if SRC_MOD == 'source_tg' else OUT

def build():
    import importlib
    z = importlib.import_module(SRC_MOD).ZF2()
    z.debug = False
    z.build_machine()
    z.tm.save(OUT)
    return z

def load_dag():
    import dag
    if not os.path.exists(TM_PATH):
        build()
    start, tbl, nodes, regidx = dag.extract(TM_PATH)
    return nodes, regidx

if __name__ == '__main__':
    z = build()
    nstates = len(set(s[0] for s in z.tm.states))
    ndag = len(set(s[0] for s in z.tm.states if s[0][0] not in '0123456789'))
    print('states', nstates, 'dag', ndag, 'framework', nstates - ndag)
    nodes, regidx = load_dag()
    print('nodes', len(nodes), 'regidx', regidx)
    from collections import Counter
    print(Counter(e[0] for n in nodes.values() for e in n))
